WITH enrollment_score_profile AS (SELECT frpm.cdscode, frpm."Enrollment (K-12)" as enrollment_k12, satscores.avgscrread as avg_read, satscores.avgscrmath as avg_math, satscores.avgscrwrite as avg_write FROM frpm INNER JOIN satscores ON frpm.cdscode = satscores.cds WHERE frpm."Enrollment (K-12)" IS NOT NULL AND satscores.avgscrread IS NOT NULL AND satscores.avgscrmath IS NOT NULL AND satscores.avgscrwrite IS NOT NULL) SELECT PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY enrollment_k12) as median_enrollment, PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY avg_read) as median_read, PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY avg_math) as median_math, PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY avg_write) as median_write FROM enrollment_score_profile;
